                        c += 1
                        continue
                    start = c
                    while c < w and g[r][c] == color:
                        c += 1
                    runs.append((r, start, c))
        return runs

    # Long side rails: sparse markers inside one rail project across matching
    # rows to the opposite rail; marked cells become 4 after their ray is drawn.
    for marker in colors:
        rails = [x for x in runs_at_edge(marker, True) if x[2] - x[1] >= 3]
        left = [x for x in rails if x[0] == 0]
        right = [x for x in rails if x[0] == w - 1]
        if not left or not right:
