            # The sparse color is the signal; preserve support for multiple points.
            signal = Counter(g[r][cc] for r, cc in signal_cells).most_common(1)[0][0]
            active = set()
            for r, cc in signal_cells:
                active.add(r - lo)
                step = 1 if cc > c else -1
                x = c + step
                while x != cc:
