                    x += step
            return g

    # Short horizontal boundary motifs project vertically in their rightmost
    # column. A signal point terminates that ray and is marked 4.
    for marker in colors:
        motifs = [x for x in runs_at_edge(marker, False) if x[2] - x[1] == 2]
